Point_2 leftmost_point(const std::vector<Point_2>& points) {
    if (points.empty()) {
        return Point_2(0.0, 0.0);
    }

    Point_2 leftmost = points[0];

    for (const Point_2& p : points) {
        if (p.x() < leftmost.x()) {
            leftmost = p;
        } else if (p.x() == leftmost.x() && p.y() < leftmost.y()) {
            leftmost = p;
        }
    }

    return leftmost;
}

